rewritten_query:
select c_count, count(*) as custdist
from (
  select c.c_custkey, coalesce(t.order_count, 0) as c_count
  from customer c
  left outer join (
    select o_custkey, count(*) as order_count
    from orders
    where o_comment not like '%unusual%deposits%'
    group by o_custkey
  ) t on c.c_custkey = t.o_custkey
) as c_orders
group by c_count
order by custdist desc, c_count desc;
